async function options(r,t){if(r.parser&&"string"==typeof r.parser)try{r.parser=await req(r.parser,t)}catch(r){throw new Error(`Loading PostCSS Parser failed: ${r.message}\n\n(@${t})`)}if(r.syntax&&"string"==typeof r.syntax)try{r.syntax=await req(r.syntax,t)}catch(r){throw new Error(`Loading PostCSS Syntax failed: ${r.message}\n\n(@${t})`)}if(r.stringifier&&"string"==typeof r.stringifier)try{r.stringifier=await req(r.stringifier,t)}catch(r){throw new Error(`Loading PostCSS Stringifier failed: ${r.message}\n\n(@${t})`)}return r}const req=require("./req.js");module.exports=options;